var p
func _ready() -> void:
	p = get_meta("viento_project")
	call_deferred("_probe")
func _snapshot(label: String, details: Dictionary = {}) -> void:
	var host = p.host.get_ref()
	print("VIENTO_BUDGET_SNAPSHOT:" + JSON.stringify({"label": label, "used": host.execution_budget.snapshot(), "details": details}))
func _probe() -> void:
	var host = p.host.get_ref()
	for index in range(64):
		p.publish_event("tick", true)
		host.flush_requests()
	p.write_state("switched", true)
	_snapshot("before-switch")
	p.request_scene("12345678-1234-4234-8234-123456789abd")

